// UI controller is injected with the workspace's state bridge; it never handles payments.
export function installCloudControls(bridge){
const dialog=document.createElement('dialog');dialog.id='cloud-dialog';dialog.setAttribute('aria-labelledby','cloud-title');
dialog.innerHTML=`<div class="modal-head"><h2 id="cloud-title">Your private workspace</h2><button type="button" class="close" id="cloud-close" aria-label="Close account dialog">×</button></div><p>Manage your account and keep your workspace available across devices.</p><button class="primary full" id="cloud-google">Continue with Google</button><p class="muted">Or use your email. Verify it before accessing cloud data.</p><form id="cloud-form"><label>Email<input id="cloud-email" type="email" required maxlength="254" autocomplete="username"></label><label>Password<input id="cloud-password" type="password" required minlength="12" maxlength="128" autocomplete="current-password"></label><div class="actions"><button class="primary" type="submit">Sign in</button><button type="button" id="cloud-register">Create account</button></div></form><div class="actions"><button id="cloud-reset">Reset password</button><button id="cloud-verify">Send verification email</button><button id="cloud-refresh">I verified my email</button></div><p id="cloud-message" role="status" aria-live="polite"></p><p class="muted">Sign out when using a shared device.</p>`;
document.body.append(dialog);let sdk=null,started=false,busy=false,authStop=()=>{};
const el=id=>document.getElementById(id),say=text=>{el('cloud-message').textContent=text;};
async function start(){if(!sdk)sdk=await import('./firebase-client.js?v=20261023-state1');if(!started){authStop();started=true;try{authStop=await sdk.connectWorkspace(bridge);}catch(error){started=false;throw error;}}return sdk;}
async function run(fn){if(busy)return;if(bridge.busy?.()){say('Wait for the workspace save to finish before changing accounts.');return;}busy=true;dialog.querySelectorAll('button,input').forEach(e=>e.disabled=true);say('Please wait…');try{await start();await fn();}catch(error){say(sdk?sdk.message(error):'Could not connect. Check your internet connection and retry.');}finally{busy=false;dialog.querySelectorAll('button,input').forEach(e=>e.disabled=false);el('cloud-password').value='';}}
async function open(show=true){bridge.begin();if(show)dialog.showModal();try{await start();}catch(error){started=false;say('Could not connect. Reconnect and retry.');bridge.status('error',null,error);}}
el('cloud-account').addEventListener('click',()=>open());el('cloud-close').addEventListener('click',()=>dialog.close());
el('cloud-google').addEventListener('click',()=>run(async()=>{await sdk.googleLogin();say('Signed in. Loading your workspace…');}));
el('cloud-form').addEventListener('submit',event=>{event.preventDefault();run(async()=>{await sdk.emailLogin(el('cloud-email').value.trim(),el('cloud-password').value);say('Signed in. Loading your workspace…');});});
el('cloud-register').addEventListener('click',()=>{if(!el('cloud-form').reportValidity())return;if(el('cloud-password').value.length<12){say('Choose at least 12 characters for a new account.');return;}run(async()=>{await sdk.register(el('cloud-email').value.trim(),el('cloud-password').value);say('Account created. Check your email for verification, then return here.');});});
el('cloud-reset').addEventListener('click',()=>{if(!el('cloud-email').reportValidity())return;run(async()=>{await sdk.resetPassword(el('cloud-email').value.trim());say('If this address has an account, a reset email has been requested.');});});
el('cloud-verify').addEventListener('click',()=>run(async()=>{await sdk.verificationEmail();say('Verification email requested for your signed-in account.');}));
el('cloud-refresh').addEventListener('click',()=>run(async()=>say(await sdk.refreshVerification()?'Email verified. Sign in again to open your workspace.':'Your email is not verified yet. Open the newest verification email first.')));
el('cloud-logout').addEventListener('click',()=>{if(!dialog.open)dialog.showModal();run(async()=>{await sdk.logout();say('Signed out. Your cloud records are no longer shown.');});});
document.addEventListener('queueflow-cloud-status',event=>{const {status,text}=event.detail;say(text);if(status==='error')started=false;if(status==='connected'&&dialog.open)dialog.close();});
document.addEventListener('click',event=>{if(bridge.isCloud()&&['connection-info','firebase-info'].includes(event.target.closest('button')?.id))open();});
el('cloud-password').minLength=6;
if(new URLSearchParams(location.search).get('workspace')==='cloud')open(false);
}
